  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Propranolol had a mean absolute oral bioavailability of 37% in human subjects after oral administration compared with IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Labetalol had an absolute oral bioavailability of 38% in hypertensive patients after a 100 mg oral dose, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C68"],
      "claim": "Fexofenadine had an absolute oral bioavailability of 33% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All informative transferred evidence molecules show absolute or systemic oral bioavailability at or above the 20% threshold, with assay-transfer scores in the high range. The strongest condition-matched numeric records consistently support high bioavailability.",
  "evidence_gaps": [
    "One evidence molecule (ilomastat) provided only qualitative 'not good' bioavailability language without a threshold-relevant numeric value, so it was treated as uninformative.",
    "Some records came from altered conditions or special populations (e.g., apple juice coadministration, cirrhosis, microdose studies) and were discounted in favor of ordinary-condition absolute measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

